package com.example.starter.plan.repo;

import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 写操作幂等记录持久化。仅缓存成功结果；同一操作类型内 requestKey 唯一。
 */
@Repository
public class IdempotencyRepository {

    /**
     * 幂等记录。
     *
     * @param requestHash  请求参数规范化后的 SHA-256
     * @param responseJson 首次成功响应快照
     */
    public record Record(String requestHash, String responseJson) {
    }

    private final JdbcTemplate jdbc;

    public IdempotencyRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按操作类型与幂等键查询记录。
     */
    public Optional<Record> find(String opType, String requestKey) {
        return jdbc.query("SELECT request_hash, response_json FROM idempotency_record"
                        + " WHERE op_type = ? AND request_key = ?",
                (rs, n) -> new Record(rs.getString("request_hash"), rs.getString("response_json")),
                opType, requestKey).stream().findFirst();
    }

    /**
     * 写入幂等记录；同键冲突时抛出 DuplicateKeyException 由上层裁决。
     */
    public void insert(String opType, String requestKey, String requestHash, String responseJson,
                       long nowMillis) {
        jdbc.update("INSERT INTO idempotency_record (op_type, request_key, request_hash, response_json, created_at)"
                        + " VALUES (?, ?, ?, ?, ?)",
                opType, requestKey, requestHash, responseJson, nowMillis);
    }
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 计划内一条区段占用，区间左闭右开 [startUtc, endUtc)。
 *
 * @param id        主键
 * @param planId    所属计划 id
 * @param seq       计划内序号，保持提交顺序
 * @param trainNo   列车编号
 * @param sectionId 区段 ID
 * @param startUtc  占用开始时刻（含），UTC
 * @param endUtc    占用结束时刻（不含），UTC，必须晚于 startUtc
 */
public record Occupancy(long id, long planId, int seq, String trainNo, String sectionId,
                        Instant startUtc, Instant endUtc) {
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 已发布计划的一条生效时隙（跨计划冲突检测与查询结果共用）。
 *
 * @param scheduleKey 所属计划业务键
 * @param trainNo     列车编号
 * @param sectionId   区段 ID
 * @param startUtc    占用开始（含），UTC
 * @param endUtc      占用结束（不含），UTC
 */
public record PublishedSlot(String scheduleKey, String trainNo, String sectionId,
                            Instant startUtc, Instant endUtc) {
}

package com.example.starter.plan.model;

import java.time.LocalDate;

/**
 * 铁路走廊日计划主记录。
 *
 * @param id          主键
 * @param scheduleKey 计划业务键，全局唯一
 * @param opDate      运营日期（Asia/Shanghai 日历日）
 * @param version     版本号，草稿占用整体替换成功一次加一
 * @param status      计划状态
 */
public record DayPlan(long id, String scheduleKey, LocalDate opDate, int version, PlanStatus status) {
}

