318	        assertThat(error.get("code").asText()).isEqualTo("SLOT_CONFLICT");
319	        JsonNode detail = error.get("details").get(0);
320	        assertThat(detail.get("type").asText()).isEqualTo("SECTION_CONFLICT");
321	        assertThat(detail.get("sectionId").asText()).isEqualTo(section);
322	        assertThat(detail.get("conflictingScheduleKey").asText()).isEqualTo(first);
323	
324	        // 冲突计划保持草稿
325	        MvcResult after = mvc.perform(get("/api/v1/plans/{key}", overlapping))
326	                .andExpect(status().isOk()).andReturn();
327	        assertThat(read(after).get("status").asText()).isEqualTo("DRAFT");
328	
329	        // 相邻时隙（09:00 紧接）合法
330	        String adjacent = key("SCH");
331	        createPlan(adjacent, occ("G3", section, iso(9), iso(10)));
332	        publishPlan(adjacent, key("REQ"));
333	
334	        // 不同区段互不影响
335	        String otherSection = key("SCH");
336	        createPlan(otherSection, occ("G4", key("SEC"), iso(8), iso(9)));
337	        publishPlan(otherSection, key("REQ"));
338	    }
339	
340	    // ---------- 幂等 ----------
341	
342	    @Test
343	    void createIdempotentReplayAndParamConflict() throws Exception {
344	        String scheduleKey = key("SCH");
345	        String requestKey = key("REQ");
346	        String body = createBody(requestKey, scheduleKey,
347	                occ("G1", key("SEC"), iso(8), iso(9)));
348	
349	        MvcResult first = mvc.perform(post("/api/v1/plans")
350	                        .contentType(MediaType.APPLICATION_JSON).content(body))
351	                .andExpect(status().isCreated()).andReturn();
352	        // 同键同参重放返回首次结果
353	        MvcResult replay = mvc.perform(post("/api/v1/plans")
354	                        .contentType(MediaType.APPLICATION_JSON).content(body))
355	                .andExpect(status().isCreated()).andReturn();
356	        assertThat(read(replay)).isEqualTo(read(first));
357	
358	        // 同键不同参 → 409
359	        mvc.perform(post("/api/v1/plans").contentType(MediaType.APPLICATION_JSON)
360	                        .content(createBody(requestKey, key("SCH"),
361	                                occ("G1", key("SEC"), iso(8), iso(9)))))
362	                .andExpect(status().isConflict());
363	    }
364	
365	    @Test
366	    void updateIdempotentReplayDoesNotIncrementTwice() throws Exception {
367	        String scheduleKey = key("SCH");
368	        createPlan(scheduleKey, occ("G1", key("SEC"), iso(8), iso(9)));
369	        String body = updateBody(key("REQ"), 1, occ("G2", key("SEC"), iso(10), iso(11)));
370	
371	        MvcResult first = mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
372	                        .contentType(MediaType.APPLICATION_JSON).content(body))
373	                .andExpect(status().isOk()).andReturn();
374	        MvcResult replay = mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
375	                        .contentType(MediaType.APPLICATION_JSON).content(body))
376	                .andExpect(status().isOk()).andReturn();
377	        assertThat(read(replay)).isEqualTo(read(first));
378	
379	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", scheduleKey))
380	                .andExpect(status().isOk()).andReturn();
381	        assertThat(read(detail).get("version").asInt()).isEqualTo(2);
382	    }
383	
384	    @Test
385	    void publishAndCancelIdempotentReplay() throws Exception {
386	        String scheduleKey = key("SCH");
387	        createPlan(scheduleKey, occ("G1", key("SEC"), iso(8), iso(9)));
388	        String publishKey = key("REQ");
389	        publishPlan(scheduleKey, publishKey);
390	
391	        // 同键重放发布返回首次结果而非 409
392	        MvcResult replay = mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
393	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(publishKey)))
394	                .andExpect(status().isOk()).andReturn();
395	        assertThat(read(replay).get("status").asText()).isEqualTo("PUBLISHED");
396	
397	        String cancelKey = key("REQ");
398	        cancelPlan(scheduleKey, cancelKey);
399	        MvcResult cancelReplay = mvc.perform(post("/api/v1/plans/{key}/cancel", scheduleKey)
400	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(cancelKey)))
401	                .andExpect(status().isOk()).andReturn();
402	        assertThat(read(cancelReplay).get("status").asText()).isEqualTo("CANCELLED");
403	    }
404	
405	    // ---------- 辅助 ----------
406	
407	    private void createPlan(String scheduleKey, String... occupancies) throws Exception {
408	        mvc.perform(post("/api/v1/plans").contentType(MediaType.APPLICATION_JSON)
409	                        .content(createBody(key("REQ"), scheduleKey, occupancies)))
410	                .andExpect(status().isCreated());
411	    }
412	
413	    private void publishPlan(String scheduleKey, String requestKey) throws Exception {
414	        mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
415	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(requestKey)))
416	                .andExpect(status().isOk());
417	    }
418	
419	    private void cancelPlan(String scheduleKey, String requestKey) throws Exception {
420	        mvc.perform(post("/api/v1/plans/{key}/cancel", scheduleKey)
421	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(requestKey)))
422	                .andExpect(status().isOk());
423	    }
424	
425	    private JsonNode read(MvcResult result) throws Exception {
426	        return objectMapper.readTree(result.getResponse().getContentAsString());
427	    }
428	
429	    private static String key(String prefix) {
430	        return prefix + "-" + UUID.randomUUID();
431	    }
432	
433	    /** 运营日当日 hour 点（Asia/Shanghai）的 UTC 时刻。 */
434	    private static String iso(int hour) {
435	        return iso(hour, 0);
436	    }
437	
438	    /** 运营日加 dayOffset 天后 hour 点（Asia/Shanghai）的 UTC 时刻。 */
439	    private static String iso(int hour, int dayOffset) {
440	        Instant instant = DAY.plusDays(dayOffset).atTime(hour, 0).atZone(SH).toInstant();
441	        return instant.toString();
442	    }
443	
444	    private static String occ(String train, String section, String startIso, String endIso) {
445	        return "{\"trainNo\":\"" + train + "\",\"sectionId\":\"" + section
446	                + "\",\"startUtc\":\"" + startIso + "\",\"endUtc\":\"" + endIso + "\"}";
447	    }
448	
449	    private static String[] manyOccs(int count) {
450	        String[] occs = new String[count];
451	        for (int i = 0; i < count; i++) {
452	            occs[i] = occ("G" + i, "SEC-M" + i, iso(8), iso(9));
453	        }
454	        return occs;
455	    }
456	
457	    private static String createBody(String requestKey, String scheduleKey, String... occupancies) {
458	        return "{\"requestKey\":\"" + requestKey + "\",\"scheduleKey\":\"" + scheduleKey
459	                + "\",\"opDate\":\"" + DAY + "\",\"occupancies\":[" + String.join(",", occupancies)
460	                + "]}";
461	    }
462	
463	    private static String updateBody(String requestKey, int expectedVersion, String... occupancies) {
464	        return "{\"requestKey\":\"" + requestKey + "\",\"expectedVersion\":" + expectedVersion
465	                + ",\"occupancies\":[" + String.join(",", occupancies) + "]}";
466	    }
467	
468	    private static String actionBody(String requestKey) {
469	        return "{\"requestKey\":\"" + requestKey + "\"}";
470	    }
471	}
