        assertThat(service.getPlan(loser).status()).isEqualTo("DRAFT");
        List<PublishedSlotView> slots = service.getPublishedSlots(DAY, secA);
        assertThat(slots).hasSize(1);
        assertThat(slots.get(0).scheduleKey()).isEqualTo(winner);
    }

