                .filter(p -> p.preemptedScheduleKey().equals(low))
                .toList();
        if (lowStatus.equals("PREEMPTED")) {
            // 抢占先提交：取消必须 409，且留有抢占记录
            assertThat(outcomes.get(1)).isEqualTo(Outcome.STATE_CONFLICT);
